const TAU = Math.PI * 2;
const clamp = (x, lo = 0, hi = 1) => Math.max(lo, Math.min(hi, x));
const smoothstep = (lo, hi, x) => {
    const t = clamp((x - lo) / (hi - lo));
    return t * t * (3 - 2 * t);
};
const finite = (x, fallback, min, max) => clamp(typeof x === 'number' && Number.isFinite(x) ? x : fallback, min, max);
