/** Keep the grid, colours, vector asset and accessibility choices intact. */
export function randomizeConfig(base = {}, seed = newRandomSeed()) {
    seed = Math.floor(finite(seed, DEFAULT_CONFIG.seed, 0, 4294967295));
    const random = seededRandom(seed);
    const between = (a, b) => a + random() * (b - a);
    const round = (v) => Math.round(v * 100) / 100;
    const choose = (values) => values[Math.floor(random() * values.length)];
    return normalizeConfig({
        ...normalizeConfig(base), pattern: 'generated', seed,
        complexity: choose([3, 4, 4, 5, 6]),
        scale: round(between(0.65, 1.65)),
        angle: Math.round(between(0, 360)),
        contrast: round(between(1.05, 2.15)),
        depth: round(between(0.85, 1)),
        speed: choose([0.5, 0.65, 0.8, 1, 1.2]),
        duration: choose([12, 16, 18, 20, 24, 30, 36]),
        shapeMotion: choose(['float', 'orbit', 'figure8']),
        shapeTravel: round(between(0.35, 0.9)),
        shapeSpin: choose([-1, 0, 0, 0, 1]),
        shapePulse: round(between(0.04, 0.18)),
