];
export const DEFAULT_CONFIG = Object.freeze({
    pattern: 'reference',
    seed: 271828,
    complexity: 4,
    shapeEnabled: true,
    shapeMotion: 'float',
    shapeMode: 'blend',
    shapeChannel: 'alpha',
    shapeSize: 0.82,
    shapeTravel: 0.65,
    shapeIntensity: 1,
    shapeSoftness: 0.12,
    shapeBackground: 0.18,
    shapeRotation: 0,
    shapeSpin: 0,
    shapePulse: 0.08,
    shapeCycles: 1,
    spacing: 26,
    minRadius: 1.05,
    maxRadius: 5.1,
    speed: 0.65,
    duration: 24,
    scale: 1,
    depth: 1,
    contrast: 1,
    angle: 0,
    dotColor: '#ececec',
    backgroundColor: '#000000',
    opacity: 0.97,
    minOpacity: 0.19,
    varyOpacity: true,
    edgeFade: 0,
    transparent: false,
    respectReducedMotion: true,
