/** Validate imported settings and enforce non-overlapping dots. */
export function normalizeConfig(input = {}) {
    const d = DEFAULT_CONFIG;
    const spacing = finite(input.spacing, d.spacing, 8, 80);
    const maxRadius = finite(input.maxRadius, d.maxRadius, 0.25, Math.min(24, spacing * 0.46));
