        shapeEnabled: typeof input.shapeEnabled === 'boolean' ? input.shapeEnabled : d.shapeEnabled,
        shapeMotion: ['float', 'orbit', 'figure8', 'still'].includes(input.shapeMotion) ? input.shapeMotion : d.shapeMotion,
        shapeMode: ['blend', 'only', 'cutout'].includes(input.shapeMode) ? input.shapeMode : d.shapeMode,
        shapeChannel: ['alpha', 'dark', 'light'].includes(input.shapeChannel) ? input.shapeChannel : d.shapeChannel,
        shapeSize: finite(input.shapeSize, d.shapeSize, 0.15, 1.6),
        shapeTravel: finite(input.shapeTravel, d.shapeTravel, 0, 1),
        shapeIntensity: finite(input.shapeIntensity, d.shapeIntensity, 0, 1),
        shapeSoftness: finite(input.shapeSoftness, d.shapeSoftness, 0, 1),
        shapeBackground: finite(input.shapeBackground, d.shapeBackground, 0, 1),
        shapeRotation: finite(input.shapeRotation, d.shapeRotation, 0, 360),
        shapeSpin: Math.round(finite(input.shapeSpin, d.shapeSpin, -3, 3)),
        shapePulse: finite(input.shapePulse, d.shapePulse, 0, 0.5),
        shapeCycles: Math.round(finite(input.shapeCycles, d.shapeCycles, 1, 4)),
        spacing,
        minRadius: finite(input.minRadius, d.minRadius, 0, maxRadius),
        maxRadius,
        speed: finite(input.speed, d.speed, 0, 3),
        duration: finite(input.duration, d.duration, 6, 120),
        scale: finite(input.scale, d.scale, 0.35, 3),
        depth: finite(input.depth, d.depth, 0, 1),
        contrast: finite(input.contrast, d.contrast, 0.35, 3),
        angle: finite(input.angle, d.angle, 0, 360),
        dotColor: colour(input.dotColor, d.dotColor),
        backgroundColor: colour(input.backgroundColor, d.backgroundColor),
        opacity: finite(input.opacity, d.opacity, 0, 1),
        minOpacity: finite(input.minOpacity, d.minOpacity, 0, 1),
        varyOpacity: typeof input.varyOpacity === 'boolean' ? input.varyOpacity : d.varyOpacity,
        edgeFade: finite(input.edgeFade, d.edgeFade, 0, 1),
        transparent: typeof input.transparent === 'boolean' ? input.transparent : d.transparent,
