const recipeCache = new Map();
function getRecipe(seed, count) {
    const key = `${seed}:${count}`;
    const existing = recipeCache.get(key);
    if (existing)
        return existing;
    const random = seededRandom(seed);
    const result = [];
    for (let i = 0; i < count; i++) {
        const direction = random() * TAU;
        const frequency = 3 + random() * 8;
        result.push({
            ax: Math.cos(direction) * frequency, ay: Math.sin(direction) * frequency,
            cycle: (1 + Math.floor(random() * 3)) * (random() > 0.5 ? 1 : -1),
            counter: 1 + Math.floor(random() * 2), offset: random() * TAU,
            warp: 0.2 + random() * 1.1, weight: (i === 0 ? 1.8 : 0.3 + random() * 0.7),
