  font-weight: 200 800;
  font-display: swap;
  font-style: normal;
}

@theme {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-surface: var(--surface);
  --color-surface-hover: var(--surface-hover);
  --color-border: var(--border);
  --color-accent: var(--accent);
  --color-accent-hover: var(--accent-hover);
  --color-text-muted: var(--text-muted);
}

:root {
  --background: #ffffff;
  --foreground: #1c1d21;
  --surface: #ffffff;
  --surface-hover: #f5f6f8;
  --border: #e6e8eb;
  --accent: #334ab3;
  --accent-hover: #293d94;
  --text-muted: #575a65;

  /* Font */
  --font-sans: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --font-serif: 'DM Serif Display', Georgia, serif;
}

body {
  background-color: var(--background);
  color: var(--foreground);
  font-family: var(--font-sans);
  /* Keep system fallback proportions close to Inter while the local face is
     being fetched. This prevents a late font swap from moving the hero. */
  font-size-adjust: 0.52;
  font-synthesis: none;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.font-serif {
  font-family: var(--font-serif);
}

/* Reduced motion respect */
@media (prefers-reduced-motion: reduce) {
  *,
  ::before,
  ::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* Base typographic styles for content */
.prose {
  color: var(--foreground);
  max-width: 65ch;
}
.prose h1, .prose h2, .prose h3, .prose h4 {
  color: var(--foreground);
  font-weight: 600;
  letter-spacing: -0.01em;
  margin-top: 2em;
  margin-bottom: 0.5em;
  line-height: 1.2;
}
.prose h1 { font-family: var(--font-serif); font-size: 2.5rem; font-weight: 400; }
.prose h2 { font-size: 1.5rem; }
.prose h3 { font-size: 1.25rem; }
.prose p { margin-top: 1em; margin-bottom: 1em; font-size: 1.125rem; }
.prose a { color: var(--accent); text-decoration: underline; text-decoration-color: transparent; transition: text-decoration-color 0.2s ease; }
.prose a:hover { text-decoration-color: var(--accent); }
.prose strong { font-weight: 600; }
.prose code { background: var(--surface-hover); padding: 0.2em 0.4em; border-radius: 0.375rem; font-size: 0.9em; font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace; }
.prose pre { background: #111216; color: #fdfcfb; padding: 1.25rem; border-radius: 1rem; overflow-x: auto; font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace; font-size: 0.875rem; margin: 1.5em 0; border: 1px solid #2b2c31; }
.prose pre code { background: transparent; padding: 0; color: inherit; font-size: inherit; }
.prose .code-block pre { padding-top: 3rem; }
.prose [id] { scroll-margin-top: 6rem; }
.prose img { width: 100%; height: auto; border: 1px solid var(--border); border-radius: 1rem; box-shadow: 0 10px 25px -5px rgba(0,0,0,0.05); }
.prose a { text-decoration-color: var(--border); }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 4px; }
.prose ul { list-style-type: disc; padding-left: 1.5em; margin: 1em 0; font-size: 1.125rem; }
.prose ol { list-style-type: decimal; padding-left: 1.5em; margin: 1em 0; font-size: 1.125rem; }
.prose li { margin-bottom: 0.5em; }
.prose blockquote { border-left: 3px solid var(--accent); padding-left: 1.25rem; color: var(--text-muted); font-style: italic; margin: 1.5em 0; font-size: 1.125rem; }
.prose hr { border: none; border-top: 1px solid var(--border); margin: 3em 0; }
