  fontSize: 48,
  speed: 50,
  countdownSeconds: 0,
  targetDurationSeconds: null,
  showTiming: true,
  // Keep the reader's existing playback behaviour when this preference is
  // first introduced.
  hideControlsWhilePlaying: true,
  pauseOnManualScroll: false,
  backgroundOpacity: 85,
  fontFamily: 'system',
  textColor: null,
