}

function booleanOrFallback(value: unknown, fallback: boolean): boolean {
  return typeof value === 'boolean' ? value : fallback;
}

function nullableNumberInRange(
  value: unknown,
  fallback: number | null,
  minimum: number,
  maximum: number,
): number | null {
  if (value === null) return null;
