.mini-phone > span { width: 25px; height: 5px; border-radius: 6px; background: #0e1728; }.mini-phone > div { height: 47px; width: 47px; margin: 22px 0 13px; display: grid; place-items: center; color: #bac6ff; background: #34446b; border-radius: 50%; }.mini-phone small { font: 4px ui-monospace, monospace; color: #aab6d3; }
