.scene-card > div:first-child { display: flex; align-items: center; gap: 10px; font: 10px ui-monospace, monospace; color: #d0d9f7; }.scene-card small { display: block; margin-top: 4px; font: 9px 'Inter', sans-serif; color: #a8b6d2; }.role-orb { background: #a7b9ff15; width: 33px; height: 33px; display: grid; place-items: center; border-radius: 50%; color: #b1c1ff; }.scene-tag { margin-left: auto; font: 7px ui-monospace, monospace; padding: 5px 7px; border: 1px solid #b0c2fa2b; border-radius: 3px; color: #bdcafa; }
.scene-card > p { font-family: 'Manrope', sans-serif; font-size: clamp(21px, 2.6vw, 32px); letter-spacing: -.035em; line-height: 1.4; margin: 24px 0 10px; }.scene-card-footer { display: flex; align-items: center; gap: 9px; border-top: 1px solid #b1c2f321; padding-top: 17px; margin-top: 24px; color: #b6c5eb; font: 7px ui-monospace, monospace; letter-spacing: .07em; }.scene-card-footer .status-dot { width: 4px; height: 4px; }.scene-disclaimer { text-align: center; color: #a3afc6; font-size: 9px; line-height: 1.8; margin: 25px 0 -25px; }
.library-section { display: grid; grid-template-columns: .85fr 1.35fr; gap: 80px; align-items: center; }.library-copy > p { color: #6c7484; font-size: 14px; line-height: 1.9; margin-top: 26px; }.file-types { display: flex; gap: 8px; margin: 25px 0; }.file-types span { font: 9px ui-monospace, monospace; border: 1px solid #dce1ea; border-radius: 4px; padding: 6px 9px; color: #66738b; }.library-image { background: #e8ecf5; border: 1px solid #d9dfeb; border-radius: 8px; padding: 20px 20px 0; overflow: hidden; box-shadow: 0 18px 40px -25px #172b5a44; }.image-label { display: flex; align-items: center; gap: 8px; font: 8px ui-monospace, monospace; color: #66728a; margin-bottom: 20px; }.library-image img { display: block; width: 100%; height: auto; border-radius: 5px 5px 0 0; box-shadow: 0 0 10px #24386210; }
.faq-section { border-top: 1px solid #e4e7ee; }.faq-grid { display: grid; grid-template-columns: 1fr 1.2fr; gap: 85px; }.faq-grid h2 { font-size: clamp(35px, 3.4vw, 48px); margin-bottom: 30px; }.faq-list details { border-bottom: 1px solid #dce1e9; }.faq-list details:first-child { border-top: 1px solid #dce1e9; }.faq-list summary { padding-block: 24px; display: flex; align-items: center; justify-content: space-between; gap: 20px; list-style: none; font-size: 13px; font-weight: 500; }.faq-list summary::-webkit-details-marker, .source-section summary::-webkit-details-marker { display: none; }.faq-list summary svg { flex-shrink: 0; color: #7a879c; transition: transform .2s; }.faq-list details[open] summary svg { transform: rotate(45deg); }.faq-list details p { font-size: 13px; color: #647087; line-height: 1.9; margin-bottom: 25px; }
.closing-section { position: relative; overflow: hidden; background: #e9edf7; border-block: 1px solid #dce2ef; padding-block: 100px; }.closing-grid { position: absolute; inset: 0; pointer-events: none; background-image: linear-gradient(#7187b718 1px, transparent 1px), linear-gradient(90deg, #7187b718 1px, transparent 1px); background-size: 50px 50px; mask-image: linear-gradient(90deg, black, transparent 32%, transparent 68%, black); transform: perspective(450px) rotateX(20deg) scale(1.25); }.closing-content { position: relative; text-align: center; }.closing-content > .eyebrow, .closing-content .hero-actions { justify-content: center; }.closing-content h2 { font-size: clamp(35px, 4.5vw, 64px); }.closing-content h2 span { color: #FF5349; }.closing-content .hero-actions { gap: 30px; }.closing-price { color: #64728d; font-size: 10px; margin-top: 23px; }.release-note { font-size: 10px; color: #66718a; margin-top: 20px; line-height: 1.8; }
.source-section { padding-block: 30px; }.source-section summary { display: flex; align-items: center; justify-content: space-between; gap: 20px; list-style: none; font-size: 12px; color: #64718a; }.source-section summary > span { display: inline-flex; align-items: center; gap: 10px; }.source-content { padding-bottom: 25px; }.source-content > p { font-size: 12px; color: #66718a; text-align: center; max-width: 600px; margin: 15px auto 0; }.source-content > p a { text-decoration: underline; }
