@media (max-width: 1100px) { .site-container { width: calc(100% - 64px); }.performance-grid { gap: 55px; }.product-stage { padding-inline: 40px; }.library-section { gap: 40px; }.premium-feature { padding: 22px; }.floating-note { right: -10px; } }
@keyframes dot-breathe { 50% { opacity:.42; transform:scale(1.035); } }
 @media (max-width: 800px) { .site-container { width: calc(100% - 40px); }.site-header { height: 72px; }.site-mobile-menu { position: fixed; top: 72px; }.section-space { padding-block: 72px; }.premium-hero { min-height: 680px; }.hero-content { padding-top: 75px; padding-bottom: 110px; }.premium-hero h1 { font-size: clamp(66px, 12vw, 92px); }.hero-description { font-size: 14px; }.flow-mesh { width: 130%; height: 90%; top: 24%; right: -50%; opacity: .6; }.use-case-grid { grid-template-columns:1fr; }.use-case-card { min-height:290px; padding:25px; }.hero-halo { background: linear-gradient(90deg, #0a0a0af8, #0a0a0a9c 65%, #0a0a0a30); }.mesh-annotation { display: none; }.hero-bottom > span { max-width: 190px; font-size: 7px; line-height: 1.8; }.principles-strip > div { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; padding-block: 22px; }.principles-strip span { font-size: 10px; gap: 8px; }.section-heading { gap: 24px; align-items: flex-start; flex-direction: column; margin-bottom: 35px; }.section-heading > p { font-size: 13px; }.product-stage { padding: 30px 18px 50px; }.preview-sidebar { display: none; }.preview-reader { padding: 18px 23px; }.preview-body { min-height: 300px; }.floating-note { display: none; }.preview-readout p { font-size: 31px; }.preview-next-line { font-size: 14px; }.product-subline { flex-direction: column; gap: 12px; }.feature-grid { grid-template-columns: 1fr; }.premium-feature + .premium-feature { border-left: 0; border-top: 1px solid #dce0e8; }.premium-feature { display: grid; grid-template-columns: 1fr 1fr; column-gap: 25px; padding: 25px; }.feature-topline { grid-column: 1/-1; }.feature-art { grid-column: 2; grid-row: 2/5; }.premium-feature h3 { margin-top: 25px; }.performance-section { padding-block: 75px; }.performance-grid { grid-template-columns: 1fr; gap: 50px; }.scene-stack { width: min(100% - 30px, 490px); margin-inline: auto; }.scene-card > p { font-size: 28px; }.library-section { grid-template-columns: 1fr; gap: 45px; }.library-copy { max-width: 470px; }.faq-grid { grid-template-columns: 1fr; gap: 30px; }.closing-section { padding-block: 75px; }.closing-content h2 { font-size: 38px; }.hero-footnote { font-size: 9px; }.eyebrow { font-size: 8px; } }
@media (max-width: 450px) { .hero-actions { gap: 10px; }.premium-button { font-size: 11px; padding: 14px 16px; gap: 12px; }.premium-hero h1 { font-size: 66px; }.premium-hero { min-height: 670px; }.hero-footnote { max-width: 240px; line-height: 1.7; }.hero-footnote > .hero-footnote-divider { display: none; }.hero-content .hero-actions { align-items: flex-start; flex-direction: column; }.hero-content .button-ghost { border: 0; padding-left: 0; }.hero-bottom > span { max-width: 155px; }.preview-reader { padding-inline: 16px; }.preview-readout p { font-size: 26px; }.preview-transport > span { font-size: 8px; }.preview-transport button { padding-inline: 7px; }.preview-transport button span { display: none; }.preview-caption { font-size: 7px; }.premium-feature { display: flex; }.feature-art { width: 100%; }.premium-feature h3 { margin-top: 0; }.scene-card { padding: 20px; }.scene-card > p { font-size: 23px; }.scene-tag { font-size: 6px; }.scene-card-footer { font-size: 6px; }.closing-content h2 { font-size: 32px; }.source-section summary { align-items: flex-start; flex-direction: column; gap: 12px; } }
